<template><div class="editor-panel"><div class="section"><h3 class="section-title">Tipo de error</h3><div class="tabs"><button v-for="tab in typeTabs" :key="tab.value" class="tab-btn" :class="{active:activeType===tab.value}" @click="activeType=tab.value">{{tab.label}}</button></div><p class="helper">La previsualización central se actualiza con el tipo seleccionado.</p></div><div class="section" v-if="currentConfig"><div class="controls-grid"><ColorPicker v-model="color" label="Color"/><ColorPicker v-model="background" label="Fondo"/><div class="input-group"><label>Borde</label><input type="text" v-model="border" class="text-input" placeholder="1px solid #FECACA"/></div><SliderControl v-model="borderRadius" label="Border radius" :min="0" :max="16" unit="px"/><SliderControl v-model="fontSize" label="Tamaño de texto" :min="11" :max="18" unit="px"/></div></div></div></template>
<script setup>
import {computed} from 'vue';import {useThemeStore} from '@/stores/themeStore.js';import {useAppStore} from '@/stores/appStore.js';import ColorPicker from '@/components/common/ColorPicker.vue';import SliderControl from '@/components/common/SliderControl.vue';const t=useThemeStore(),a=useAppStore();const typeTabs=[{value:'validation',label:'Validación'},{value:'operation',label:'Operación'},{value:'businessRule',label:'Regla de negocio'}];const activeType=computed({get:()=>a.componentSelection.errors,set:v=>a.setComponentSelection('errors',v)});const currentConfig=computed(()=>t.theme.errors[activeType.value]);const b=p=>computed({get:()=>currentConfig.value?.[p],set:v=>t.updateError(activeType.value,p,v)});const color=b('color'),background=b('background'),border=b('border'),borderRadius=b('borderRadius'),fontSize=b('fontSize')
